import torch

def run(grad_output, self_input, target, weight, reduction, ignore_index, total_weight):
    ri = reduction
    nd = self_input.dim()
    if nd <= 2:
        return torch.ops.aten.nll_loss_backward(grad_output, self_input, target, weight, ri, ignore_index, total_weight)
    C = self_input.shape[1]
    s2 = self_input.permute(0, *range(2, nd), 1).reshape(-1, C)
    t2 = target.reshape(-1)
    go = grad_output.reshape(-1) if ri == 0 else grad_output
    g2 = torch.ops.aten.nll_loss_backward(go, s2, t2, weight, ri, ignore_index, total_weight)
    N = self_input.shape[0]
    g = g2.reshape((N, *self_input.shape[2:], C))
    inv = (0, nd - 1, *range(1, nd - 1))
    return g.permute(inv).contiguous()

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    self_shape = ctx["self_input__shape"]
    dtype = _dtype_from_context(ctx, "self_input")
    classes = self_shape[1]
    target_shape = ctx["target__shape"]
    target = torch.randint(
        0, classes, target_shape, dtype=_dtype_from_context(ctx, "target"), device=device
    )
    self_input = torch.randn(self_shape, dtype=dtype, device=device)
    if "weight__shape" in ctx:
        weight = torch.randn(
            ctx["weight__shape"], dtype=_dtype_from_context(ctx, "weight"), device=device
        )
        selected_weight = weight[target]
    else:
        weight = None
        selected_weight = torch.ones(target_shape, dtype=dtype, device=device)
    mask = (target != ctx["ignore_index"]).to(dtype)
    total_weight = (selected_weight * mask).sum()
    grad_output = torch.randn(
        ctx["grad_output__shape"],
        dtype=_dtype_from_context(ctx, "grad_output"),
        device=device,
    )
    result = {
        "grad_output": grad_output,
        "self_input": self_input,
        "target": target,
        "total_weight": total_weight,
    }
    if weight is not None:
        result["weight"] = weight
    return result
